/**
 * Resolve the chain from action params and assert it is an EVM chain.
 *
 * @param params - Action payload containing an optional `chain`.
 * @param context - Resolved operation context (fallback chain source).
 * @returns The resolved EVM chain definition.
 * @throws {KitError} If the resolved chain is not EVM.
 */ function assertEvmChain(params, context) {
    const chain = params.chain ?? context.chain;
    if (chain.type !== 'evm') {
        throw new KitError({
            ...InputError.INVALID_CHAIN,
            recoverability: 'FATAL',
            message: `Expected EVM chain definition, but received chain type: ${chain.type}`
        });
    }
    return chain;
}

/**
 * Resolve the Gateway Minter contract address for a chain that supports Gateway v1.
 *
 * @param chain - Chain from context or params (must have gateway.contracts.v1).
 * @returns Gateway Minter address as 0x string.
 * @throws {KitError} INVALID_CHAIN if the chain does not support Gateway v1.
 */ function getGatewayMinterAddress(chain) {
    if (!isGatewayV1Supported(chain)) {
        throw new KitError({
            ...InputError.INVALID_CHAIN,
            recoverability: 'FATAL',
            message: `Gateway Minter address not found: chain "${chain.name}" does not have Gateway v1 contracts configured.`,
            cause: {
                trace: {
                    chain: chain.name
                }
            }
        });
    }
    return chain.gateway.contracts.v1.minter;
}

/**
 * Resolve the Gateway Wallet contract address for a chain that supports Gateway v1.
 *
 * @param chain - Chain from context or params (must have gateway.contracts.v1).
 * @returns Gateway Wallet address as 0x string.
 * @throws {KitError} INVALID_CHAIN if the chain does not support Gateway v1.
 */ function getGatewayWalletAddress(chain) {
    if (!isGatewayV1Supported(chain)) {
        throw new KitError({
            ...InputError.INVALID_CHAIN,
            recoverability: 'FATAL',
            message: `Gateway Wallet address not found: chain "${chain.name}" does not have Gateway v1 contracts configured.`,
            cause: {
                trace: {
                    chain: chain.name
                }
            }
        });
    }
    return chain.gateway.contracts.v1.wallet;
}

/**
 * Resolve signature arguments for Gateway deposit operations that accept
 * either packed `signature` bytes or a `(v, r, s)` triple.
 *
 * @param commonArgs - The non-signature arguments that precede the signature.
 * @param fields - The raw signature fields from the action payload.
 * @param functionName - Name used in the error message on validation failure.
 * @returns Combined argument array ready for `adapter.prepare`.
 * @throws {KitError} VALIDATION_FAILED if neither form is provided.
 */ function resolveSignatureArgs(commonArgs, fields, functionName) {
    if (fields.signature !== undefined) {
        return [
            ...commonArgs,
            fields.signature
        ];
    }
    // Validate v, r, s components with specific error messages
    const missingComponents = [
        {
            name: 'v',
            value: fields.v
        },
        {
            name: 'r',
            value: fields.r
        },
        {
            name: 's',
            value: fields.s
        }
    ].filter((c)=>c.value === undefined).map((c)=>c.name);
    if (missingComponents.length === 3) {
        throw new KitError({
            ...InputError.VALIDATION_FAILED,
            recoverability: 'FATAL',
            message: `${functionName} requires either signature bytes or v, r, s`
        });
    }
    const [firstMissing] = missingComponents;
    if (firstMissing !== undefined) {
        throw new KitError({
            ...InputError.VALIDATION_FAILED,
            recoverability: 'FATAL',
            message: `${functionName}: missing signature component '${firstMissing}'`
        });
    }
    if (typeof fields.v !== 'number') {
        throw new KitError({
            ...InputError.VALIDATION_FAILED,
            recoverability: 'FATAL',
            message: `${functionName}: 'v' must be a number (27 or 28), got ${typeof fields.v}`
        });
    }
    if (typeof fields.r !== 'string' || !fields.r.startsWith('0x')) {
        throw new KitError({
            ...InputError.VALIDATION_FAILED,
            recoverability: 'FATAL',
            message: `${functionName}: 'r' must be a 0x-prefixed hex string`
        });
    }
    if (typeof fields.s !== 'string' || !fields.s.startsWith('0x')) {
        throw new KitError({
            ...InputError.VALIDATION_FAILED,
            recoverability: 'FATAL',
            message: `${functionName}: 's' must be a 0x-prefixed hex string`
        });
    }
    return [
        ...commonArgs,
        fields.v,
        fields.r,
        fields.s
    ];
}

/**
 * Prepares an EVM Gateway Wallet `deposit` transaction.
 *
 * Deposits tokens after the caller has approved the Gateway contract. The resulting
 * balance belongs to the caller. Corresponds to
 * [GatewayWallet.deposit](https://developers.circle.com/gateway/references/contract-interfaces-and-events#deposit).
 *
 * @param params - Action payload: token address and value (smallest unit).
 * @param adapter - EVM adapter for chain context and preparation.
 * @param context - Resolved operation context (chain must support Gateway v1).
 * @returns Prepared chain request for the deposit call.
 * @throws KitError INVALID_CHAIN when the chain is not EVM, or when the chain
 *   does not support Gateway v1 (via {@link getGatewayWalletAddress}).
 *
 * @example
 * ```typescript
 * import { deposit } from '@core/adapter-evm'
 * const prepared = await deposit(
 *   { token: '0x...', value: 1_000_000n },
 *   adapter,
 *   context,
 * )
 * const txHash = await prepared.execute()
 * ```
 */ const deposit = async (params, adapter, context)=>{
    const chain = assertEvmChain(params, context);
    const walletAddress = getGatewayWalletAddress(chain);
    return adapter.prepare({
        type: 'evm',
        abi: gatewayWalletAbi,
        address: walletAddress,
        functionName: 'deposit',
        args: [
            params.token,
            params.value
        ]
    }, context);
};

