    // chainId/verifyingContract).  Validate with the gateway-specific schema.
    assertGatewayTypedData(params.typedData);
    // Cast to TypedData so the adapter's signTypedData accepts it.
    // The adapter's eip712DomainSchema treats chainId/verifyingContract as
    // optional by design — Gateway domains omit them because replay protection
    // is embedded in the signed message body (sourceDomain, sourceContract, salt).
    const typedData = params.typedData;
